BEGIN;
SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='500ms';
DO $reserve$
DECLARE job_started timestamptz:=clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtextextended('comparator_strict:atomic-v1',0))
    OR EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE status IN ('planned','running','halted','unknown'))
    OR EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE job_key='ce1-ce200-63c87276f4d78ba8e780052e303c') THEN RAISE EXCEPTION 'ce200_exclusive_or_replay'; END IF;
  IF EXISTS(SELECT 1 FROM pg_stat_activity WHERE cardinality(pg_blocking_pids(pid))>0
    OR (pid<>pg_backend_pid() AND state='active' AND query_start<clock_timestamp()-interval '30 seconds')) THEN RAISE EXCEPTION 'ce200_health_stop'; END IF;
  UPDATE comparator_strict.execution_budget SET
    sql_ms_reserved=sql_ms_reserved+10000,read_rows_reserved=read_rows_reserved+500,
    bytes_reserved=bytes_reserved+131072,write_rows_reserved=write_rows_reserved+3,updated_at=clock_timestamp()
    WHERE project_ref='gkffvigcnsesbaihycay' AND budget_date=DATE '2026-09-03'
      AND approval_reference='CE-200-corpus-v1' AND bytes_limit=134217728 AND read_rows_limit=50000
      AND bytes_reserved+131072<=bytes_limit AND read_rows_reserved+500<=read_rows_limit AND write_rows_reserved+3<=2000;
  IF NOT FOUND THEN RAISE EXCEPTION 'ce200_budget'; END IF;
  INSERT INTO comparator_strict.execution_jobs(id,project_ref,operation_key,sql_sha256,status,started_at,deadline_at,job_key,operation_hash,budget_date,reservation)
    VALUES(gen_random_uuid(),'gkffvigcnsesbaihycay','ce200-location-fingerprints','04e0ca6f6787767b8dd1d63a2ed4ddc668facdf7ed6afc89f549705cba6d1fb2','running',job_started,job_started+interval '20 minutes','ce1-ce200-63c87276f4d78ba8e780052e303c','63c87276f4d78ba8e780052e303c6a5c57bb818c1a0065ab74c5a11c1eb7af6a',DATE '2026-09-03','{"sqlMs":10000,"readRows":500,"writeRows":3,"responseBytes":131072}'::jsonb);
END $reserve$;
COMMIT;
BEGIN;
SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='500ms';
DO $payload$
DECLARE payload jsonb; data jsonb; started timestamptz:=clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtextextended('comparator_strict:atomic-v1',0))
    OR NOT EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE job_key='ce1-ce200-63c87276f4d78ba8e780052e303c' AND status='running' AND operation_hash='63c87276f4d78ba8e780052e303c6a5c57bb818c1a0065ab74c5a11c1eb7af6a' AND deadline_at>clock_timestamp()) THEN RAISE EXCEPTION 'ce200_lease'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) INTO data FROM (SELECT l.id,md5(to_jsonb(l)::text) AS source_row_md5 FROM public.catalog_location_prices l
      WHERE l.store='consum' AND l.product_id IN (SELECT id FROM public.consum_products WHERE published IS TRUE AND (display_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)' OR category_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)|b[ií]fidus'))
      AND l.id COLLATE "C" > '' COLLATE "C" ORDER BY l.id COLLATE "C" LIMIT 500) q;
  payload:=jsonb_build_object('job_key','ce1-ce200-63c87276f4d78ba8e780052e303c','operation_hash','63c87276f4d78ba8e780052e303c6a5c57bb818c1a0065ab74c5a11c1eb7af6a',
    'project_ref','gkffvigcnsesbaihycay','captured_at',started,'kind','location-fingerprints','store','consum',
    'cursor','','rows',data,'row_count',jsonb_array_length(data),'elapsed_ms',extract(epoch FROM clock_timestamp()-started)*1000);
  IF jsonb_array_length(data)>500 OR octet_length(payload::text)>122880 THEN RAISE EXCEPTION 'ce200_result_limit'; END IF;
  UPDATE comparator_strict.execution_jobs SET status='succeeded',finished_at=clock_timestamp(),
    receipt=jsonb_build_object('payload_sha256',encode(sha256(convert_to(payload::text,'UTF8')),'hex'),'row_count',jsonb_array_length(data),'payload_bytes',octet_length(payload::text),'elapsed_ms',payload->'elapsed_ms') WHERE job_key='ce1-ce200-63c87276f4d78ba8e780052e303c';
  PERFORM set_config('comparator_strict.ce200_response',payload::text,true);
END $payload$;
SELECT current_setting('comparator_strict.ce200_response')::jsonb AS evidence;
